@startuml

class Faculty {
  + Name : string
}

class Institute {
  + Name : string
  + Address : string
}

class Employee {
  + SocialSecurityNumber : string
  + Name : string
  + EmailAddress : string
}

class ResearchStaff extends Employee {
  + FieldOfResearch : string
}

class AdministrativeStaff extends Employee {}

class ResearchAssistant extends ResearchStaff {}

class Lecturer extends ResearchAssistant {}

class Course {
  + ID : int
  + Name : string
  + WeeklyDuration : int
}

class ProjectInvolvement {
  + Name : string
  + StartDate : date
  + EndDate : date
  + Hours : int
}

Faculty "1" *-- "*" Institute
Faculty "1" -- "1" Employee : headed by
Institute "*" -- "1" Faculty : part of
ResearchAssistant "*" -- "1..*" Institute : assigned to
ResearchAssistant "1" -- "*" ProjectInvolvement : involved in
ProjectInvolvement "*" -- "1" Course : for
Lecturer "1" -- "*" Course : teaches

@enduml

